-- Enable real row-level security for every user-scoped table.
-- See scripts/033_enable_rls.sql for the mechanism (SET LOCAL ROLE prisma_application + app.wallet).
-- Policies are inert for the superuser connection until RLS_MODE=enforce.

ALTER TABLE a2a_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE a2a_messages FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS rls_a2a_messages ON a2a_messages;
CREATE POLICY rls_a2a_messages ON a2a_messages FOR ALL USING (lower(from_address) = lower(current_setting('app.wallet', true))) WITH CHECK (lower(from_address) = lower(current_setting('app.wallet', true)));
