DROP POLICY IF EXISTS rls_batch_chunks ON batch_chunks;
CREATE POLICY rls_batch_chunks ON batch_chunks FOR ALL USING (EXISTS (SELECT 1 FROM batch_jobs p WHERE p.id = batch_chunks.job_id AND lower(p.user_id) = lower(current_setting('app.wallet', true)))) WITH CHECK (EXISTS (SELECT 1 FROM batch_jobs p WHERE p.id = batch_chunks.job_id AND lower(p.user_id) = lower(current_setting('app.wallet', true))));
